package com.aai.app

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Base64

/**
 * Expression portraits cropped directly from the ARIS expression strip supplied
 * by the user. These are still images; no procedural face drawing or motion.
 */
internal object CharacterExpressions {
    private val encoded = mapOf(
        "happy" to "",
        "surprised" to "",
        "sad" to "",
        "laugh" to ""
    )
    private val cache = mutableMapOf<String, Bitmap>()

    fun bitmap(context: Context, key: String): Bitmap? {
        val data = encoded[key] ?: return null
        return cache.getOrPut(key) {
            val bytes = Base64.decode(data, Base64.DEFAULT)
            BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
                ?: throw IllegalStateException("Invalid ARIS expression image: $key")
        }
    }
}
